import { resolveCardAssetPath } from '../../data/asset_paths'
import type { MarkdownFile } from '../../data/data_types'
import { generateUuid } from '../../data/uuid'
import type { CardOperationContext } from './card_operation_context'
import { dialogService } from '../dialog_service'

const BASE64_CHUNK_SIZE = 32768
const MAXIMUM_FILE_NAME_ATTEMPTS = 100
const PASTED_IMAGE_NAME_PREFIX = 'pasted-image-'
const SUPPORTED_CLIPBOARD_IMAGE_EXTENSIONS: Readonly<Record<string, string>> = {
    'image/gif': '.gif',
    'image/jpeg': '.jpg',
    'image/png': '.png',
    'image/svg+xml': '.svg',
    'image/webp': '.webp',
}

export interface SavedCardImage {
    fileName: string
    path: string
}

/** Saves an image before inserting its reference, removing the asset if insertion fails. */
export async function saveAndInsertPastedImage(
    file: File,
    insertMarkdown: (markdown: string) => void,
    saveImage: (file: File) => Promise<SavedCardImage>,
    deleteImage: (path: string) => Promise<void>,
) {
    const savedImage = await saveImage(file)
    try {
        insertMarkdown(`![pasted image](<${savedImage.fileName}>)`)
    } catch (error) {
        try {
            await deleteImage(savedImage.path)
        } catch (cleanupError) {
            dialogService.error(cleanupError, { fallbackMessage: `Could not remove ${savedImage.path}` })
        }
        throw error
    }

    return savedImage
}

/** Maps a supported clipboard image MIME type to its persisted extension. */
export function clipboardImageExtension(mimeType: string) {
    const extension = SUPPORTED_CLIPBOARD_IMAGE_EXTENSIONS[mimeType.toLowerCase()]
    if (!extension) throw new Error(`Unsupported clipboard image type: ${mimeType}`)

    return extension
}

/** Encodes clipboard binary content for storage commit APIs. */
export async function clipboardImageBase64(file: File) {
    const bytes = new Uint8Array(await file.arrayBuffer())
    let binary = ''
    for (let offset = 0; offset < bytes.length; offset += BASE64_CHUNK_SIZE) {
        binary += String.fromCharCode(...bytes.subarray(offset, offset + BASE64_CHUNK_SIZE))
    }

    return btoa(binary)
}

/** Generates a unique bare image name and resolves it beside the destination card. */
export function createAvailablePastedImagePath(
    cardPath: string,
    mimeType: string,
    existingPaths: Iterable<string>,
    createIdentifier: () => string = () => generateUuid(),
): SavedCardImage {
    const extension = clipboardImageExtension(mimeType)
    const normalizedExistingPaths = new Set([...existingPaths].map((path) => path.replace(/\\/gu, '/').toLowerCase()))

    for (let attempt = 0; attempt < MAXIMUM_FILE_NAME_ATTEMPTS; attempt += 1) {
        const fileName = `${PASTED_IMAGE_NAME_PREFIX}${createIdentifier()}${extension}`
        const path = resolveCardAssetPath(cardPath, fileName)
        if (!normalizedExistingPaths.has(path.toLowerCase())) return { fileName, path }
    }

    throw new Error('Could not generate an available pasted image file name')
}

/** Persists and removes image assets owned by card editor workflows. */
export class CardImageOperations {
    private readonly context: CardOperationContext
    private readonly reservedPaths = new Set<string>()

    constructor(context: CardOperationContext) {
        this.context = context
    }

    saveForCard(cardPath: string, file: File) {
        return this.save(cardPath, file)
    }

    saveForNewCard(file: File) {
        const { config } = this.context.requireProject('save a pasted image')
        const draftCardPath = `${config.workingFolder}/new-card-draft.md`

        return this.save(draftCardPath, file)
    }

    async delete(path: string) {
        const { config, project, storage } = this.context.requireProject('delete a pasted image')
        const existingFile = this.context.dependencies.files().find((file) => file.path === path)
        const repositoryFile = this.context.dependencies.snapshot()?.repositoryFiles.includes(path) ?? false
        if (!existingFile && !repositoryFile) throw new Error(`Cannot delete a pasted image that is not loaded: ${path}`)

        await storage.deleteFile({
            branch: project.branch,
            message: `Delete ${path}`,
            path,
            ...(existingFile?.sha ? { sha: existingFile.sha } : {}),
        })
        this.context.dependencies.deleteFile(path, [], config.workingFolder)
        this.context.dependencies.dispatchChanged()

        if (config.pushMode === 'auto') {
            try {
                await storage.push(project)
            } catch (error) {
                dialogService.error(error, { fallbackMessage: `${path} was deleted locally, but could not be pushed` })
            }
        }
    }

    private async save(cardPath: string, file: File) {
        const { project } = this.context.requireProject('save a pasted image')
        const existingPaths = [
            ...this.context.dependencies.files().map(({ path }) => path),
            ...(this.context.dependencies.snapshot()?.repositoryFiles ?? []),
            ...this.reservedPaths,
        ]
        const savedImage = createAvailablePastedImagePath(cardPath, file.type, existingPaths)
        this.reservedPaths.add(savedImage.path)

        try {
            const imageFile: MarkdownFile = {
                content: await clipboardImageBase64(file),
                encoding: 'base64',
                path: savedImage.path,
            }
            await this.context.commitAndMergeFiles({
                branch: project.branch,
                files: [imageFile],
                message: `Add ${savedImage.path}`,
            }, [imageFile])
            this.context.dependencies.dispatchPersistenceChanged()
            void this.context.pushCreatedItem('Pasted image')

            return savedImage
        } finally {
            this.reservedPaths.delete(savedImage.path)
        }
    }
}

import type { DataService } from '../../../services/data/data_service'
import type { CardType } from '../../../data/data_types'
import { dialogService } from '../../../services/dialog_service'
import {
    openFilesService,
    type CardOpenDocument,
    type OpenDocumentChangedDetail,
    type OpenFilesService,
} from '../../../services/open_files_service'
import {
    MarkdownDataSourceBase,
    type MarkdownBindingKind,
    type MarkdownDocumentTarget,
} from './markdown_data_source'
import { saveAndInsertPastedImage } from '../../../services/data/card_image_operations'

export type CardBinding = Exclude<MarkdownBindingKind, 'list-action'>
type CardMarkdownOwner = EventTarget & Pick<DataService, 'getState'> & {
    cards: Pick<DataService['cards'],
        'deletePastedImage' | 'savePastedImageForCard' | 'toggleCardPolicy' | 'updateCardBody'
        | 'updateCardHeaderFields' | 'updateCardTitle' | 'updateCardType'>
}
type ListCardOwner = EventTarget & Pick<OpenFilesService, 'getSnapshot'>

export interface CardDocumentClosedDetail {
    binding: 'list-card'
    document: CardOpenDocument
}

function cardTarget(target: MarkdownDocumentTarget): asserts target is { document: CardOpenDocument } {
    if (target.document.kind !== 'card') throw new Error('Card Markdown source requires a card document')
}

function readCardMarkdown(target: MarkdownDocumentTarget) {
    cardTarget(target)
    return target.document.getDraft().content
}

function editCardMarkdown(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string) {
    if (binding === 'list-action') throw new Error('Card Markdown source cannot use list-action binding')
    cardTarget(target)
    target.document.updateDraft({ content: markdown }, binding)
}

/** Reads and writes card body Markdown through focused card operations. */
export class CardMarkdownDataSource extends MarkdownDataSourceBase {
    private listCardOwner: ListCardOwner | null = null
    private service: CardMarkdownOwner | null = null

    init(service: CardMarkdownOwner) {
        if (this.service) return

        this.service = service
        openFilesService.addEventListener('documentChanged', this.handleDocumentChanged)
    }

    dispose() {
        openFilesService.removeEventListener('documentChanged', this.handleDocumentChanged)
        this.setBoardDocument(null)
    }

    bindListCards(owner: ListCardOwner) {
        if (this.listCardOwner === owner) return
        if (this.listCardOwner) throw new Error('Card Markdown data source already has a list-card owner')

        this.listCardOwner = owner
        owner.addEventListener('changed', this.handleListCardsChanged)
        owner.addEventListener('removed', this.handleListCardRemoved)
        this.syncListCardBinding()
    }

    getActiveDocument(binding: CardBinding) {
        const target = this.getActiveTarget(binding)
        return target?.document.kind === 'card' ? target.document : null
    }

    getActiveCard(binding: CardBinding) {
        return this.getActiveDocument(binding)?.getObject() ?? null
    }

    getProjectKey() {
        const { project } = this.requireService().getState()
        if (!project) throw new Error('Cannot resolve a card project before a project is open')

        return `${project.id}:${project.branch}`
    }

    updateActiveCardTitle(binding: CardBinding, title: string) {
        const document = this.requireActiveDocument(binding)
        this.requireService().cards.updateCardTitle(document.path, title)
            .catch((error: unknown) => {
                dialogService.error(error, { fallbackMessage: `Title update failed: ${document.path}` })
            })
    }

    updateActiveCardType(binding: CardBinding, type: CardType) {
        const document = this.requireActiveDocument(binding)

        return this.requireService().cards.updateCardType(document.path, type)
            .catch((error: unknown) => {
                dialogService.error(error, { fallbackMessage: `Card type update failed: ${document.path}` })
            })
    }

    updateActiveCardHeaderField(binding: CardBinding, key: string, value: string) {
        const document = this.requireActiveDocument(binding)
        if (key !== 'author') throw new Error(`Unsupported editable card header field: ${key}`)

        this.requireService().cards.updateCardHeaderFields(document.path, { [key]: value })
    }

    toggleActiveCardPolicy(binding: CardBinding, policyKey: string) {
        const document = this.requireActiveDocument(binding)
        this.requireService().cards.toggleCardPolicy(document.path, policyKey)
    }

    async pasteImage(binding: CardBinding, file: File, insertMarkdown: (markdown: string) => void) {
        const document = this.requireActiveDocument(binding)
        const { cards } = this.requireService()

        await saveAndInsertPastedImage(
            file,
            insertMarkdown,
            (clipboardFile) => cards.savePastedImageForCard(document.path, clipboardFile),
            (path) => cards.deletePastedImage(path),
        )
    }

    readonly getMarkdown = readCardMarkdown
    readonly edit = editCardMarkdown

    commit(binding: MarkdownBindingKind, target: MarkdownDocumentTarget, markdown: string) {
        CardMarkdownDataSource.requireCardBinding(binding)
        cardTarget(target)
        try {
            const draft = target.document.getDraft()
            if (draft.content !== markdown) target.document.updateDraft({ content: markdown }, binding)
            this.requireService().cards.updateCardBody(
                target.document.path,
                markdown,
                target.document.createSaveReference(),
            )
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Body update failed: ${target.document.path}` })
            return false
        }
    }

    setBoardDocument(document: CardOpenDocument | null, discard = false) {
        this.setActiveTarget('board-card', document ? { document } : null, discard)
    }

    private readonly handleDocumentChanged = (event: Event) => {
        const { document, origin, type } = (event as CustomEvent<OpenDocumentChangedDetail>).detail
        if (document.kind !== 'card') return

        if (type === 'renewed') {
            this.dispatchEvent(new Event('cardsChanged'))
            return
        }
        if (type !== 'draft') return

        const originBinding = typeof origin === 'string' ? origin as MarkdownBindingKind : null
        this.dispatchMarkdownReplaced({ originBinding, target: { document } })
    }

    private readonly handleListCardsChanged = () => this.syncListCardBinding()

    private readonly handleListCardRemoved = (event: Event) => {
        const { document } = (event as CustomEvent<{ document: ReturnType<ListCardOwner['getSnapshot']>['activeDocument'] }>).detail
        if (!document || document.kind !== 'card') return

        const detail: CardDocumentClosedDetail = { binding: 'list-card', document }
        this.dispatchEvent(new CustomEvent<CardDocumentClosedDetail>('cardDocumentClosed', { detail }))
    }

    private syncListCardBinding() {
        const activeDocument = this.listCardOwner?.getSnapshot().activeDocument ?? null
        this.setActiveTarget('list-card', activeDocument?.kind === 'card' ? { document: activeDocument } : null)
    }

    private requireActiveDocument(binding: CardBinding) {
        const document = this.getActiveDocument(binding)
        if (!document) throw new Error(`Cannot update a card without an active ${binding} document`)

        return document
    }

    private static requireCardBinding(binding: MarkdownBindingKind) {
        if (binding === 'list-action') throw new Error('Card Markdown source cannot use list-action binding')
    }

    private requireService() {
        if (!this.service) throw new Error('Card Markdown data source is not initialized')
        return this.service
    }
}

export const cardMarkdownDataSource = new CardMarkdownDataSource()
cardMarkdownDataSource.bindListCards(openFilesService)

import { Box } from '@mui/material'
import { memo, useCallback } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { ACTION_PROMPT_PLACEHOLDERS } from '../../data/action_placeholders'
import { MarkdownEditor } from '../editor/markdown_editor'
import type { CardMarkdownDataSource } from '../editor/data_sources/card_markdown_data_source'
import type { MarkdownDocumentHistoryStore } from '../editor/history/markdown_document_history_store'
import type { MarkdownToolbarContext } from '../editor/toolbar/markdown_toolbar_context'
import { CardPopupToolbarControls } from './card_popup_toolbar_controls'
import { useProjectReadOnly } from '../hooks/use_project_read_only'
import { attachFilesToCardMarkdown } from '../../services/attachments/attachment_workflow'
import { resolveCardImageSource } from '../../services/attachments/card_image_source'

interface CardBodyEditorProps {
    cardTypes: CardTypeConfig[]
    dataSource: CardMarkdownDataSource
    historyStore: MarkdownDocumentHistoryStore
    isMobile?: boolean
    isFullscreen: boolean
    onToggleFullscreen: () => void
    overlayContainer?: HTMLElement | null
    statusColors: Map<string, string>
}

/**
 * Body editing surface for a card, bound directly to the card Markdown data source.
 */
export const CardBodyEditor = memo(function CardBodyEditor(props: CardBodyEditorProps) {
    const {cardTypes, dataSource, historyStore, isFullscreen, isMobile = false, onToggleFullscreen, overlayContainer, statusColors} = props
    const readOnly = useProjectReadOnly()
    const handleImagePaste = useCallback(
        (file: File, insertMarkdown: (markdown: string) => void) => dataSource.pasteImage('board-card', file, insertMarkdown),
        [dataSource],
    )
    const handleAttachments = useCallback((files: File[], insertMarkdown: (markdown: string) => void) => {
        const card = dataSource.getActiveCard('board-card')
        if (!card) throw new Error('Cannot attach files without an active board card')

        return attachFilesToCardMarkdown(card.path, files, insertMarkdown)
    }, [dataSource])
    const handleImagePreview = useCallback(async (src: string) => {
        const card = dataSource.getActiveCard('board-card')
        if (!card) return src

        return resolveCardImageSource(card.path, src)
    }, [dataSource])
    const ToolbarContents = useCallback(
        (toolbarContext: MarkdownToolbarContext) => (
            <CardPopupToolbarControls
                cardTypes={cardTypes}
                dataSource={dataSource}
                isFullscreen={isFullscreen}
                isMobile={isMobile}
                onAttachFiles={toolbarContext.onAttachFiles}
                onToggleFullscreen={onToggleFullscreen}
                readOnly={readOnly}
                statusColors={statusColors}
            />
        ),
        [cardTypes, dataSource, isFullscreen, isMobile, onToggleFullscreen, readOnly, statusColors],
    )
    return (
        <Box
            sx={{
                '& .mdxeditor-content': {
                    boxSizing: 'border-box',
                    minHeight: 220,
                    padding: '26px 28px 32px',
                },
                '& [class*="_toolbarButton_"], & [class*="_toolbarToggleItem_"]': {
                    alignItems: 'center',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    height: 30,
                    justifyContent: 'center',
                    width: 30,
                },
                '& [class*="_toolbarButton_"]:hover, & [class*="_toolbarToggleItem_"]:hover': {
                    backgroundColor: 'background.paper',
                    color: 'text.primary',
                },
                '& [class*="_toolbarRoot_"]': {
                    backgroundColor: 'action.selected',
                    borderRadius: '9px',
                    boxSizing: 'border-box',
                    color: 'text.secondary',
                    flexShrink: 0,
                    height: 40,
                    margin: '14px 20px 0',
                    padding: '0 6px',
                    width: 'auto',
                },
                '& [class*="_toolbarRoot_"] div[role="separator"]': {
                    borderColor: 'divider',
                    height: 20,
                    margin: '0 4px',
                },
                flex: 1,
                minHeight: 0,
                overflow: 'auto',
            }}
        >
            <MarkdownEditor
                attachmentHandler={handleAttachments}
                binding="board-card"
                dataSource={dataSource}
                flushOnBlur
                historyStore={historyStore}
                imagePasteHandler={handleImagePaste}
                imagePreviewHandler={handleImagePreview}
                overlayContainer={overlayContainer}
                placeholders={ACTION_PROMPT_PLACEHOLDERS}
                readOnly={readOnly}
                toolbarContents={ToolbarContents}
            />
        </Box>
    )
})

